			function search() {
			    
			    // 조회조건 유효성 체크
			    if (!util.validate(app, "grpSearch")) return false;
			    
			    // 조회조건에 사례번호 추가
			    var dmSearch = app.lookup("dmSearch");
			    var caseMngNoView = dmSearch.getValue("CASE_MNG_NO_VIEW");
			    var sCaseMngNo = "";
			    var sCaseMngOdrno = "";
			    
			    if(caseMngNoView.toString().length >= 13){
			        if(caseMngNoView.toString().length == 13){
			            sCaseMngNo = "CS" + caseMngNoView;
			        } else if(caseMngNoView.toString().length == 14){
			            sCaseMngNo = "CS" + caseMngNoView.toString().substr(0, 13);
			            sCaseMngOdrno = caseMngNoView.toString().substr(13, 1);
			        } else if(caseMngNoView.toString().length == 15){ // 사례관리차수가 2자리인 경우도 있다
			            sCaseMngNo = "CS" + caseMngNoView.toString().substr(0, 13);
			            sCaseMngOdrno = caseMngNoView.toString().substr(13, 2);
			        }
			        dmSearch.setValue("CASE_MNG_NO", sCaseMngNo);        
			        dmSearch.setValue("CASE_MNG_ODRNO", sCaseMngOdrno);
			    } else {
			        if(!ValueUtil.isNull(caseMngNoView)){
			            util.Msg.alert(app, "사례번호를 정확히 입력해 주세요.");
			            return false
			        }
			    }
			    
			    doList();
			}

